const inputData = $('Execute Workflow Trigger').first()?.json || {};
const umbral = Number(inputData.umbral_usd) || 100000.00;

const importadores = $('Obtener Importadores').all().map(i => i.json);
const declaraciones = $('Obtener Declaraciones').all().map(i => i.json);
const detalles = $('Obtener Detalles').all().map(i => i.json);

const decMap = new Map(declaraciones.map(d => [d.id_declaracion, d.id_importador]));
const totales = new Map();
const duasVistos = new Map();

for (const det of detalles) {
  const idImp = decMap.get(det.id_declaracion);
  if (!idImp) continue;
  const valorLinea = Number(det.cantidad) * Number(det.valor_unitario);
  totales.set(idImp, (totales.get(idImp) || 0) + valorLinea);

  if (!duasVistos.has(idImp)) duasVistos.set(idImp, new Set());
  duasVistos.get(idImp).add(det.id_declaracion);
}

const filtrados = [];
for (const imp of importadores) {
  const total = Math.round((totales.get(imp.id_importador) || 0) * 100) / 100;
  if (total > umbral) {
    filtrados.push({
      identificacion_tributaria: imp.identificacion_tributaria,
      razon_social: imp.razon_social,
      cantidad_declaraciones: duasVistos.has(imp.id_importador) ? duasVistos.get(imp.id_importador).size : 0,
      valor_total_acumulado_usd: total,
      moneda: 'USD'
    });
  }
}

filtrados.sort((a, b) => b.valor_total_acumulado_usd - a.valor_total_acumulado_usd);

return [{
  json: {
    estado: 'exitoso',
    herramienta: 'consultar_importadores_por_umbral',
    filtros: { umbral_usd: umbral, moneda: 'USD' },
    total_registros: filtrados.length,
    es_parcial: false,
    datos: filtrados
  }
}];
